sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float radius;
uniform float feather;
uniform float aspect;
uniform float rotation;
uniform float ambient;
layout(color) uniform half4 darkColor;
layout(color) uniform half4 lightColor;
uniform float lightAmount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 d = rot2((coord / size - center) * float2(size.x / size.y, 1.0), radians(rotation));
    d.x /= aspect;
    float beam = 1.0 - smoothstep(radius, radius + feather, length(d));
    float3 dark = mix(s * ambient, float3(darkColor.rgb), 0.15 * (1.0 - ambient));
    float3 o = mix(dark, s, beam);
    o += float3(lightColor.rgb) * beam * beam * lightAmount * 0.5;
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), opacity);
}
